namespace SrpLab;
public sealed class EnrollmentRoster { private readonly HashSet<string> _seated=new(StringComparer.OrdinalIgnoreCase); private readonly List<string> _waitlist=new(); public string Register(string email,int capacity) { if(_seated.Contains(email)||_waitlist.Contains(email)) return "ALREADY_REGISTERED"; if(_seated.Count<capacity){_seated.Add(email);return "SEATED";} _waitlist.Add(email);return $"WAITLIST:{_waitlist.Count}"; } public int WaitlistPosition(string email) { var index=_waitlist.FindIndex(x=>x.Equals(email,StringComparison.OrdinalIgnoreCase)); return index<0?-1:index+1; } public bool IsSeated(string email){return _seated.Contains(email);} public void Promote(int seats,int capacity){while(seats>0&&_waitlist.Count>0&&_seated.Count<capacity){var next=_waitlist[0];_waitlist.RemoveAt(0);_seated.Add(next);seats--;}} }
public sealed class WelcomePacketComposer { public string Compose(string code,bool seated,int position,string name) { var status=seated?"confirmed seat":$"waitlist #{position}"; return $"# Welcome to {code}\nHi {name},\nYour status: **{status}**.\nBring a laptop. Discord onboarding link: https://example.invalid/{code.ToLowerInvariant()}\n"; } }
public sealed class TuitionInvoiceFormatter { public string Format(string code,decimal tuition,bool seated) { if(!seated)return $"{code},WAITLIST,0.00";var vat=Math.Round(tuition*.14m,2);return $"{code},TUITION,{tuition:0.00},VAT,{vat:0.00},TOTAL,{(tuition+vat):0.00}"; } }
